// The widget's interface in German.
//
// Keyed by the English text the code writes, so the code stays the one source of what the
// interface says and an English string with no entry here simply stays English. Documents are not
// translated here: they have their own words per language in doc/lang.js. Nor is anything a
// business typed, nor the email wording it sends its clients (Settings → Messages is theirs).
//
// Entries are exact: a key matches a whole text node, attribute or option, trimmed. Text built from
// values ("Added 3 columns.") is matched by DE_PATTERNS below.

const KINDS = {
  'quote / estimate': 'Angebot', quote: 'Angebot', 'proforma invoice': 'Proformarechnung', invoice: 'Rechnung',
  receipt: 'Quittung', 'credit note': 'Gutschrift', 'statement of account': 'Kontoauszug',
  'delivery note': 'Lieferschein', 'packing slip': 'Packzettel', document: 'Dokument',
};
const kind = (s) => KINDS[String(s).toLowerCase()] || s;
const KIND_WORDS = Object.keys(KINDS).join('|');

const ROLES = { client: 'Kunden', catalogue: 'Katalog', invoices: 'Rechnungen', clients: 'Kunden', 'line items': 'Positionen' };
const plural = (n, one, many) => (String(n) === '1' ? one : many);

