/** One part of a trade's summary line: "invoices", "Classic layout", "numbered INV-2026-0001". */
function summaryPart(p) {
  const s = p.trim();
  const plurals = { 'quote / estimates': 'Angebote', invoices: 'Rechnungen', receipts: 'Quittungen', 'packing slips': 'Packzettel', 'proforma invoices': 'Proformarechnungen', 'credit notes': 'Gutschriften', 'delivery notes': 'Lieferscheine', 'statement of accounts': 'Kontoauszüge' };
  if (plurals[s]) return plurals[s];
  if (s === 'no tax') return 'keine Steuer';
  if (s === 'prices include tax') return 'Preise inkl. Steuer';
  if (s === 'numbers restart monthly') return 'Nummern beginnen monatlich neu';
  let m = /^(.+) layout$/.exec(s); if (m) return `Layout ${DE[m[1]] || m[1]}`;
  m = /^numbered (.+)$/.exec(s); if (m) return `nummeriert ${m[1]}`;
  m = /^asks for the (.+)$/.exec(s); if (m) return `fragt nach: ${m[1]}`;
  return s;
}
